/**
 * FORECOURT WORKS LTD — Multi-product Breakdown Loss Calculator
 */
(function () {
  'use strict';

  const EMBEDDED_LOGO_MARK_PNG = 'data:image/png;base64,';

  const PRODUCT_META = {
    'PMS': { label: 'PMS', full: 'Petrol / Motor Spirit', color: [13, 71, 140], css: 'PMS' },
    'AGO': { label: 'AGO', full: 'Automotive Gas Oil', color: [180, 83, 9], css: 'AGO' },
    'V.POWER': { label: 'V. POWER', full: 'Premium grade', color: [109, 40, 217], css: 'VPOWER' },
    'IK': { label: 'IK', full: 'Illuminating Kerosene', color: [15, 118, 110], css: 'IK' }
  };

  const PERIODS = [
    { key: 'minute', label: 'Per minute' },
    { key: 'hour', label: 'Per hour' },
    { key: 'day', label: 'Per day' },
    { key: 'week', label: 'Per week' },
    { key: 'month', label: 'Per month' },
    { key: 'quarter', label: 'Per quarter' },
    { key: 'semi', label: 'Semi-annual' },
    { key: 'year', label: 'Annual' }
  ];

  const state = {
    selected: [],
    lastCalc: null
  };

  const $ = (s, root) => (root || document).querySelector(s);
  const $$ = (s, root) => Array.from((root || document).querySelectorAll(s));

  function toast(msg, type) {
    const el = $('#toast');
    el.textContent = msg;
    el.className = 'toast show' + (type ? ' ' + type : '');
    setTimeout(() => { el.className = 'toast'; }, 3000);
  }

  function formatKES(n) {
    if (n == null || isNaN(n)) return '—';
    return 'KES ' + Number(n).toLocaleString('en-KE', { maximumFractionDigits: 0 });
  }
  function formatL(n) {
    if (n == null || isNaN(n)) return '—';
    return Number(n).toLocaleString('en-KE', { maximumFractionDigits: 1 }) + ' L';
  }
  function formatDateDDMonYYYY(iso) {
    if (!iso) return '—';
    const d = new Date(iso + 'T00:00:00');
    if (isNaN(d.getTime())) return iso;
    const m = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
    return String(d.getDate()).padStart(2, '0') + '-' + m[d.getMonth()] + '-' + d.getFullYear();
  }
  function todayISO() {
    return new Date().toISOString().slice(0, 10);
  }

  function switchTab(id) {
    $$('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === id));
    $$('.tab-panel').forEach(p => p.classList.toggle('active', p.id === 'tab-' + id));
  }

  function panelId(product) {
    return product === 'V.POWER' ? 'panel-VPOWER' : 'panel-' + product;
  }

  function updateProductUI() {
    const n = state.selected.length;
    const note = $('#limit-note');
    if (n === 0) {
      note.textContent = 'Select at least one product. Maximum 3 at the same time.';
      note.className = 'limit-note';
    } else if (n >= 3) {
      note.textContent = 'Maximum 3 products selected. Deselect one to choose another.';
      note.className = 'limit-note warn';
    } else {
      note.textContent = n + ' product(s) selected — you can add up to ' + (3 - n) + ' more.';
      note.className = 'limit-note';
    }

    $$('.p-toggle').forEach(t => {
      const p = t.dataset.product;
      const on = state.selected.includes(p);
      t.className = 'p-toggle' + (on ? ' on-' + PRODUCT_META[p].css : '');
    });

    ['PMS', 'AGO', 'V.POWER', 'IK'].forEach(p => {
      const panel = document.getElementById(panelId(p));
      if (!panel) return;
      panel.classList.toggle('active', state.selected.includes(p));
    });

    const panels = $('#product-panels');
    panels.className = 'product-panels cols-' + Math.max(1, Math.min(3, n || 1));

    updateAllVpn();
  }

  function toggleProduct(product) {
    const idx = state.selected.indexOf(product);
    if (idx >= 0) {
      state.selected.splice(idx, 1);
    } else {
      if (state.selected.length >= 3) {
        toast('Maximum 3 products at once', 'error');
        return;
      }
      state.selected.push(product);
    }
    updateProductUI();
  }

  function updateVpn(product) {
    const panel = document.getElementById(panelId(product));
    if (!panel) return;
    const vol = parseFloat($('.vol-day', panel).value) || 0;
    const nz = parseFloat($('.nozzles', panel).value) || 0;
    const el = $('.vpn', panel);
    if (vol > 0 && nz > 0) {
      el.textContent = (vol / nz).toLocaleString('en-KE', { maximumFractionDigits: 1 });
    } else {
      el.textContent = '—';
    }
  }

  function updateAllVpn() {
    state.selected.forEach(updateVpn);
    ['PMS', 'AGO', 'V.POWER', 'IK'].forEach(updateVpn);
  }

  function hoursForPeriod(key, hoursDay, daysWeek) {
    switch (key) {
      case 'minute': return 1 / 60;
      case 'hour': return 1;
      case 'day': return hoursDay;
      case 'week': return hoursDay * daysWeek;
      case 'month': return hoursDay * (daysWeek / 7) * 30;
      case 'quarter': return hoursDay * (daysWeek / 7) * 90;
      case 'semi': return hoursDay * (daysWeek / 7) * 182.5;
      case 'year': return hoursDay * (daysWeek / 7) * 365;
      default: return 0;
    }
  }

  function readSite() {
    return {
      client: ($('#client-name').value || '').trim(),
      site: ($('#site-location').value || '').trim(),
      preparedBy: ($('#prepared-by').value || '').trim(),
      date: $('#calc-date').value || todayISO(),
      hoursDay: parseFloat($('#hours-day').value) || 18,
      daysWeek: parseFloat($('#days-week').value) || 7,
      repairCost: parseFloat($('#repair-cost').value) || 0
    };
  }

  function readProduct(product) {
    const panel = document.getElementById(panelId(product));
    const volDay = parseFloat($('.vol-day', panel).value) || 0;
    const nozzles = parseFloat($('.nozzles', panel).value) || 1;
    const price = parseFloat($('.price', panel).value) || 0;
    const marginRaw = parseFloat($('.margin', panel).value);
    const margin = isNaN(marginRaw) ? null : marginRaw;
    const volPerNozzle = nozzles > 0 ? volDay / nozzles : 0;
    return { product, volDay, nozzles, volPerNozzle, price, margin };
  }

  function calcProduct(p, site) {
    // Full product stream offline: use total daily volume for that product
    const litersPerOpHour = site.hoursDay > 0 ? p.volDay / site.hoursDay : 0;
    const rows = PERIODS.map(per => {
      const hrs = hoursForPeriod(per.key, site.hoursDay, site.daysWeek);
      const liters = litersPerOpHour * hrs;
      return {
        key: per.key,
        label: per.label,
        liters,
        revenue: liters * p.price,
        margin: p.margin != null ? liters * p.margin : null
      };
    });
    return { ...p, litersPerOpHour, rows };
  }

  function calculate() {
    if (!state.selected.length) {
      toast('Select at least one product', 'error');
      return;
    }
    const site = readSite();
    const products = [];
    for (const code of state.selected) {
      const p = readProduct(code);
      if (p.volDay <= 0) {
        toast('Enter daily volume for ' + code, 'error');
        return;
      }
      if (p.price <= 0) {
        toast('Enter price for ' + code, 'error');
        return;
      }
      if (p.nozzles < 1) {
        toast('Nozzles must be at least 1 for ' + code, 'error');
        return;
      }
      products.push(calcProduct(p, site));
    }

    const totalDayRev = products.reduce((s, p) => s + p.rows.find(r => r.key === 'day').revenue, 0);
    const totalDayL = products.reduce((s, p) => s + p.rows.find(r => r.key === 'day').liters, 0);
    const totalMonthRev = products.reduce((s, p) => s + p.rows.find(r => r.key === 'month').revenue, 0);
    const totalYearRev = products.reduce((s, p) => s + p.rows.find(r => r.key === 'year').revenue, 0);

    state.lastCalc = { site, products, totalDayRev, totalDayL, totalMonthRev, totalYearRev };
    renderResults();
    renderPitch();
    switchTab('results');
    toast('Loss calculation updated', 'success');
  }

  function renderResults() {
    const c = state.lastCalc;
    if (!c) return;
    $('#impact-main').textContent = formatKES(c.totalDayRev) + ' / day';
    $('#impact-sub').textContent = formatL(c.totalDayL) + ' combined · ' + formatKES(c.totalMonthRev) + ' / month · ' + formatKES(c.totalYearRev) + ' / year';

    const grid = $('#results-grid');
    grid.className = 'results-grid cols-' + Math.min(3, c.products.length);
    grid.innerHTML = c.products.map(p => {
      const meta = PRODUCT_META[p.product];
      const rows = p.rows.map(r => `
        <tr>
          <td>${r.label}</td>
          <td class="liters">${formatL(r.liters)}</td>
          <td class="kes">${formatKES(r.revenue)}</td>
        </tr>`).join('');
      return `
        <div class="result-col">
          <div class="col-head ${meta.css}">${meta.label} · ${meta.full}</div>
          <table>
            <thead><tr><th>Period</th><th>Litres</th><th>Revenue</th></tr></thead>
            <tbody>${rows}</tbody>
          </table>
          <div class="meta">
            ${formatL(p.volDay)}/day across ${p.nozzles} nozzle(s) ·
            <b>${formatL(p.volPerNozzle)}</b>/nozzle/day ·
            ${formatKES(p.price)}/L
            ${p.margin != null ? ' · margin ' + formatKES(p.margin) + '/L' : ''}
          </div>
        </div>`;
    }).join('');
  }

  function renderPitch() {
    const c = state.lastCalc;
    if (!c) return;
    const lines = c.products.map(p => {
      const day = p.rows.find(r => r.key === 'day');
      return `<li><b>${p.product}</b>: ${formatKES(day.revenue)}/day (${formatL(day.liters)}) — ${p.nozzles} nozzle(s), ${formatL(p.volPerNozzle)}/nozzle</li>`;
    }).join('');
    $('#pitch-body').innerHTML = `
      <p><b>${c.site.client || 'Client'}</b> · ${c.site.site || 'Site'} · ${formatDateDDMonYYYY(c.site.date)}</p>
      <p style="margin-top:8px;">If the selected product stream(s) stay offline, estimated combined sales exposure is:</p>
      <ul>${lines}</ul>
      <p><b style="color:#b91c1c;">Total ≈ ${formatKES(c.totalDayRev)} per day</b> · ${formatKES(c.totalMonthRev)} per month · ${formatKES(c.totalYearRev)} per year.</p>
      ${c.site.repairCost > 0 ? `<p>A typical repair/response cost of <b>${formatKES(c.site.repairCost)}</b> is about <b>${(c.totalDayRev / c.site.repairCost).toFixed(1)}×</b> recovered by protecting a single day of these sales.</p>` : ''}
      <p style="margin-top:10px;"><b>Close:</b> Forecourt Works R&amp;M — preventive inspection and rapid response — is built to stop these losses before the island goes quiet.</p>
      <p style="color:#64748b;font-size:0.82rem;margin-top:8px;">Illustrative demonstration based on entered daily volumes and prices.</p>
    `;
  }

  function generatePDF() {
    if (!state.lastCalc) {
      toast('Calculate first', 'error');
      return;
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pageW = 210, pageH = 297;
    const outer = 8;
    const margin = 14;
    const usable = pageW - margin * 2;
    const navy = [13, 71, 140];
    const dark = [15, 23, 42];
    const grey = [100, 116, 139];
    const red = [185, 28, 28];
    const footerBand = 12; // reserved above outer boundary for footer text
    const contentBottom = pageH - outer - footerBand - 2;

    const c = state.lastCalc;
    const nProd = c.products.length;

    // Boundary — footer lives inside, above bottom edge
    function drawBoundary() {
      doc.setDrawColor(...navy);
      doc.setLineWidth(0.7);
      doc.rect(outer, outer, pageW - outer * 2, pageH - outer * 2);
      doc.setLineWidth(0.25);
      doc.rect(outer + 1.2, outer + 1.2, pageW - (outer + 1.2) * 2, pageH - (outer + 1.2) * 2);
    }

    function drawFooter() {
      const fy = pageH - outer - 4;
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...grey);
      doc.setDrawColor(...navy);
      doc.setLineWidth(0.2);
      doc.line(margin, fy - 4, pageW - margin, fy - 4);
      doc.text('FORECOURT WORKS LIMITED · Ramco Court, GT 3B, South C · +254 729-002-087 · sales@forecourtworks.co.ke', margin, fy - 1);
      doc.text('FSW-DEMO-LOSS-01 · Page 1 of 1', pageW - margin, fy - 1, { align: 'right' });
    }

    drawBoundary();

    let y = outer + 5;

    // Logo top-right (compact)
    try {
      doc.addImage(EMBEDDED_LOGO_MARK_PNG, 'PNG', pageW - margin - 38, outer + 3, 36, 24);
    } catch (_) {}

    // Header left
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(...navy);
    doc.text('FORECOURT WORKS LIMITED', margin, y + 3);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(...dark);
    doc.text('Ramco Court, GT 3B, South C, Nairobi  |  +254 729-002-087', margin, y + 7);
    doc.setFont('helvetica', 'italic');
    doc.setTextColor(196, 92, 10);
    doc.setFontSize(8);
    doc.text('Engineering Reliability Into Every Forecourt', margin, y + 11);
    y += 16;

    doc.setDrawColor(...navy);
    doc.setLineWidth(0.35);
    doc.line(margin, y, pageW - margin, y);
    y += 5;

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...navy);
    doc.text('DISPENSER BREAKDOWN — FINANCIAL LOSS ILLUSTRATION', pageW / 2, y, { align: 'center' });
    y += 5;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(...grey);
    doc.text('Multi-product sales exposure demo for R&M service conversations', pageW / 2, y, { align: 'center' });
    y += 5;

    // Client strip
    doc.setFillColor(241, 245, 249);
    doc.setDrawColor(...navy);
    doc.setLineWidth(0.25);
    doc.rect(margin, y, usable, 11, 'FD');
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(...dark);
    doc.text('Client: ' + (c.site.client || '—') + '   |   Site: ' + (c.site.site || '—'), margin + 2, y + 4.5);
    doc.text('Date: ' + formatDateDDMonYYYY(c.site.date) + '   |   Prepared: ' + (c.site.preparedBy || '—') + '   |   Hours/day: ' + c.site.hoursDay + '   |   Days/week: ' + c.site.daysWeek, margin + 2, y + 9);
    y += 14;

    // Impact band
    doc.setFillColor(127, 29, 29);
    doc.rect(margin, y, usable, 12, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(255, 255, 255);
    doc.text('COMBINED AT RISK: ' + formatKES(c.totalDayRev) + ' / DAY', pageW / 2, y + 5, { align: 'center' });
    doc.setFontSize(7.5);
    doc.text(formatL(c.totalDayL) + '   ·   ' + formatKES(c.totalMonthRev) + ' / month   ·   ' + formatKES(c.totalYearRev) + ' / year', pageW / 2, y + 9.5, { align: 'center' });
    y += 15;

    // Product columns
    const gap = 3;
    const colW = (usable - gap * (nProd - 1)) / nProd;
    const tableTop = y;
    const rowH = 5.2;
    const headH = 8;
    const metaH = 10;
    const titleH = 6;

    c.products.forEach((p, i) => {
      const meta = PRODUCT_META[p.product];
      const x0 = margin + i * (colW + gap);
      let cy = tableTop;

      // Column header
      doc.setFillColor(...meta.color);
      doc.rect(x0, cy, colW, headH, 'F');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(255, 255, 255);
      doc.text(meta.label, x0 + colW / 2, cy + 5.2, { align: 'center' });
      cy += headH;

      // Sub meta
      doc.setFillColor(248, 250, 252);
      doc.setDrawColor(200, 210, 220);
      doc.rect(x0, cy, colW, metaH, 'FD');
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(5.8);
      doc.setTextColor(...dark);
      doc.text(formatL(p.volDay) + '/day · ' + p.nozzles + ' nz', x0 + 1.5, cy + 3.5);
      doc.text(formatL(p.volPerNozzle) + '/nz · ' + formatKES(p.price) + '/L', x0 + 1.5, cy + 7.5);
      cy += metaH;

      // Table header
      doc.setFillColor(...meta.color);
      doc.setGState && doc.setGState(new doc.GState({ opacity: 0.85 }));
      doc.rect(x0, cy, colW, 5.5, 'F');
      try { doc.setGState(new doc.GState({ opacity: 1 })); } catch (_) {}
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(6);
      doc.setTextColor(255, 255, 255);
      doc.text('Period', x0 + 1.2, cy + 3.8);
      doc.text('Litres', x0 + colW * 0.42, cy + 3.8);
      doc.text('KES', x0 + colW * 0.72, cy + 3.8);
      cy += 5.5;

      p.rows.forEach((r, ri) => {
        if (ri % 2 === 0) {
          doc.setFillColor(248, 250, 252);
          doc.rect(x0, cy, colW, rowH, 'F');
        }
        doc.setDrawColor(226, 232, 240);
        doc.setLineWidth(0.1);
        doc.line(x0, cy + rowH, x0 + colW, cy + rowH);
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(6);
        doc.setTextColor(...dark);
        doc.text(r.label, x0 + 1.2, cy + 3.6);
        doc.setTextColor(...navy);
        doc.text(formatL(r.liters).replace(' L', ''), x0 + colW * 0.42, cy + 3.6);
        doc.setTextColor(...red);
        doc.setFont('helvetica', 'bold');
        const kesShort = Number(r.revenue).toLocaleString('en-KE', { maximumFractionDigits: 0 });
        doc.text(kesShort, x0 + colW * 0.72, cy + 3.6);
        cy += rowH;
      });

      // Column border
      doc.setDrawColor(...meta.color);
      doc.setLineWidth(0.4);
      doc.rect(x0, tableTop, colW, cy - tableTop);
    });

    y = tableTop + headH + metaH + 5.5 + PERIODS.length * rowH + 6;

    // Pitch (compact)
    if (y < contentBottom - 28) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(...navy);
      doc.text('WHY R&M MATTERS', margin, y);
      y += 4;
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.setTextColor(...dark);
      let pitch = 'Offline nozzles convert directly into lost pump sales. Combined exposure above is based on the station\'s own daily volumes. ';
      if (c.site.repairCost > 0) {
        pitch += 'Repair/response cost ' + formatKES(c.site.repairCost) + ' is roughly ' + (c.totalDayRev / c.site.repairCost).toFixed(1) + '× recoverable by protecting one day of these sales. ';
      }
      pitch += 'Forecourt Works R&M prevents unplanned outages through inspection and rapid response.';
      const pl = doc.splitTextToSize(pitch, usable);
      doc.text(pl, margin, y);
      y += pl.length * 3.3 + 4;
    }

    if (y < contentBottom - 12) {
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.setTextColor(...dark);
      doc.text('Client sign: ________________________    FSW: ________________________    Date: ____________', margin, y);
      y += 5;
      doc.setFont('helvetica', 'italic');
      doc.setFontSize(6);
      doc.setTextColor(...grey);
      doc.text('Illustrative demonstration only — not a financial audit or tax computation.', margin, y);
    }

    drawFooter();

    const names = c.products.map(p => p.product.replace('.', '')).join('-');
    const safeClient = (c.site.client || 'Client').replace(/[\\/:*?"<>|]/g, '-').slice(0, 30);
    const fileName = 'FSW Loss - ' + names + ' - ' + safeClient + '.pdf';
    doc.save(fileName);
    toast('PDF saved (1 page): ' + fileName, 'success');
  }

  function init() {
    $('#calc-date').value = todayISO();
    $('#date-hint').textContent = 'Selected: ' + formatDateDDMonYYYY(todayISO());
    $('#calc-date').addEventListener('change', () => {
      $('#date-hint').textContent = 'Selected: ' + formatDateDDMonYYYY($('#calc-date').value);
    });

    // Default: PMS selected
    state.selected = ['PMS'];
    updateProductUI();

    $$('.p-toggle').forEach(t => {
      t.addEventListener('click', () => toggleProduct(t.dataset.product));
    });

    $$('.vol-day, .nozzles').forEach(el => {
      el.addEventListener('input', () => updateVpn(el.dataset.product));
    });

    $$('.tab-btn').forEach(btn => {
      btn.addEventListener('click', () => switchTab(btn.dataset.tab));
    });

    $('#btn-calculate').addEventListener('click', calculate);
    $('#btn-reset').addEventListener('click', () => {
      state.selected = ['PMS'];
      $$('.vol-day, .price, .margin').forEach(el => { el.value = ''; });
      $$('.nozzles').forEach(el => { el.value = '1'; });
      updateProductUI();
      toast('Reset');
    });
    $('#btn-pdf').addEventListener('click', generatePDF);
    $('#btn-pdf-2').addEventListener('click', generatePDF);
    $('#btn-to-pitch').addEventListener('click', () => switchTab('pitch'));

    document.addEventListener('input', (e) => {
      if (e.target.classList.contains('auto-caps') && e.target.type === 'text') {
        const s = e.target.selectionStart;
        e.target.value = e.target.value.toUpperCase();
        try { e.target.setSelectionRange(s, s); } catch (_) {}
      }
    });
  }

  document.addEventListener('DOMContentLoaded', init);
})();
